#include <cstdio>
#include <cstring>
#include <cstddef>
#include <type_traits>

// 与 C 共享的 POD：布局必须与 C 编译器一致 → 要求标准布局 + 可平凡复制
struct PodC { int id; double value; char tag; };

// extern "C"：C 链接，不做名称修饰（C++ 名字会被 mangle 成 _Z...）
extern "C" int c_add(int a, int b);
extern "C" int c_add(int a, int b) { return a + b; }

// 模板函数的完整签名（含实参类型）→ 展示 C++ 名称修饰的"可读形式"
template <class T> const char* pretty() { return __PRETTY_FUNCTION__; }

int main() {
    printf("c_add(2,3)=%d\n", c_add(2, 3));

    bool layout_ok = std::is_standard_layout<PodC>::value
                  && std::is_trivially_copyable<PodC>::value;
    printf("PodC 标准布局=%d 可平凡复制=%d\n",
           (int)std::is_standard_layout<PodC>::value,
           (int)std::is_trivially_copyable<PodC>::value);
    printf("PodC sizeof=%zu align=%zu off_value=%zu off_tag=%zu\n",
           sizeof(PodC), alignof(PodC), offsetof(PodC, value), offsetof(PodC, tag));
    printf("ABI 跨语言安全: %d\n", (int)layout_ok);

    const char* pf = pretty<int>();
    printf("C++ 函数签名含实参类型: %d\n", (int)(std::strstr(pf, "T = int") != nullptr));
    printf("签名文本: %s\n", pf);
    return 0;
}
